def mcq(tp, s, n, qen, qvi, ans, wrongs, xe, xv, rx, lvl=1, fig=None):
    it = dict(kind='mcq', q=B(qen, qvi), opts=O([ans] + wrongs), correct=0, explain=B(xe, xv), level=lvl, topic=TT[tp], src=B(*SRC[s](n)), origin='bo_sung', fixed_order=False, check='source text')
